   "script": "redesign/team/F3/avionics.py",
   "function": "vibe",
   "equation": "k = n E a^2 / h; fn = sqrt(k/m)/2pi; T(r) = sqrt((1+(2 z r)^2)/((1-r^2)^2+(2 z r)^2)), r = f/fn, f1P = rpm/60",
